return items.map((item, idx) => {
  const action = item.json || {};
  const candidates = (Array.isArray(action.candidates) ? action.candidates : []).map(c => ({
    id: c.id,
    task: c.task,
    lead: c.lead,
    status: c.status,
    latest_note: c.latest_note || c.note,
    next_step: c.next_step
  }));
  const userPrompt = `You decide whether a newly proposed WIP task already exists in the current open task list for the same project_client. If yes, output decision=match with the existing task id and a confidence 0..1. Otherwise output decision=new.\n\nPROJECT_CLIENT: ${action.project_client}\n\nNEW TASK PROPOSAL:\n${JSON.stringify({ task: action.task, lead: action.lead, status: action.status, latest_note: action.latest_note, next_step: action.next_step }, null, 2)}\n\nEXISTING OPEN TASKS FOR THIS PROJECT:\n${JSON.stringify(candidates, null, 2)}\n\nReturn strict JSON: { "decision": "match" | "new", "match_id": "<uuid or null>", "confidence": <0..1>, "reason": "<short>" }`;
  return { json: { ...action, candidates, matcherUserPrompt: userPrompt }, pairedItem: { item: idx } };
});

const threshold = Number($('Merge System Config').first().json.wipConfidenceThreshold ?? 0.82);
return items.map((item, idx) => {
  let action = {};
  try { action = $('Build WIP Match Prompt').itemMatching(idx).json || {}; } catch (e) { action = {}; }
  const m = (item.json && item.json.output) || item.json || {};
  const matched = m.decision === 'match' && m.match_id && Number(m.confidence || 0) >= threshold;
  return {
    json: {
      ...action,
      matcher: m,
      action: matched ? 'update' : 'create',
      existing_task_id: matched ? m.match_id : action.existing_task_id,
      matcherMatched: matched
    },
    pairedItem: { item: idx }
  };
});

return items.map((item, idx) => {
  const s = item.json || {};
  return {
    json: {
      action_applied: s.action_applied || null,
      task: s.task || '',
      project_client: s.project_client || '',
      lead: s.lead || '',
      latest_note: s.latest_note || '',
      next_step: s.next_step || '',
      status: s.status || '',
      existing_task_id: s.existing_task_id || null,
      wip_task_id: s.wip_task_id || null,
      errors: Array.isArray(s.errors) ? s.errors : []
    },
    pairedItem: { item: idx }
  };
});

const existingRows = $('Lookup Existing Meeting (Pre-Loop)').all().map(i => i.json || {});
const rowsByEvent = new Map();
for (const row of existingRows) {
  if (row.calendar_event_id && row.id && !rowsByEvent.has(row.calendar_event_id)) {
    rowsByEvent.set(row.calendar_event_id, row);
  }
}
return $('Clean Transcript').all().map(item => {
  const clean = item.json || {};
  return { json: { ...clean, existing_meeting_row: rowsByEvent.get(clean.calendar_event_id) || null } };
});

const meetings = $('Attach Meeting To Context').all().map(i => i.json);
const taskRows = items.map(i => i.json || {});
const targetDate = $('Resolve Date').first().json.targetDate;
return meetings.map(context => {
  const meetingId = context.meeting_id;
  const meeting = context.existing_meeting && context.existing_meeting.id ? context.existing_meeting : (meetingId ? { id: meetingId } : null);
  const existingTasksForThisMeeting = taskRows.filter(r => r && r.meeting_id === meetingId && r.wip_task_id);
  const createdToday = meeting && meeting.created_at ? String(meeting.created_at).slice(0,10) === targetDate : false;
  return { json: { ...context, existing_meeting: meeting, meeting_exists: !!meeting, doubleRunWarning: !!meeting && createdToday && existingTasksForThisMeeting.length > 0 } };
});

const out = [];
for (let i = 0; i < items.length; i++) {
  const row = items[i].json || {};
  const upstream = $('Rejoin Meetings By Event').itemMatching(i).json;
  const { existing_meeting_row, ...clean } = upstream;
  const existing_meeting = existing_meeting_row || row;
  const meeting_id = existing_meeting.id || row.id || clean.meeting_id || null;
  out.push({ json: { ...clean, meeting_id, existing_meeting } });
}
return out;

const action = $json;
const guard = $('Loop Per Meeting').first().json;
const meeting_id = guard.meeting_id;
return [{ json: { ...action, meeting_id, missing_meeting_id: !meeting_id, existing_meeting: guard.existing_meeting || null, meeting_exists: !!guard.meeting_exists, doubleRunWarning: !!guard.doubleRunWarning } }];

const base = $('Attach Meeting ID').itemMatching(0).json;
const shouldCascade = base.action_applied === 'complete' && !!base.wip_task_id;
return [{ json: { ...base, shouldCascade, close_wip_task_id: shouldCascade ? base.wip_task_id : null } }];

const applied = $('Normalize WIP Result').all().map(i => i.json);
let cascades = [];
try { cascades = $('Cascade Close Tickets').all().map(i => i.json); } catch (e) { cascades = []; }
const counts = { tasks_created: 0, tasks_updated: 0, tasks_completed: 0, tickets_auto_closed: 0, errors: [], doubleRunWarning: false, created: [], updated: [], completed: [] };
const truncate = (value, max = 140) => {
  const text = String(value || '').replace(/\s+/g, ' ').trim();
  return text.length > max ? text.slice(0, max - 1) + '…' : text;
};
const itemize = (a) => {
  const entry = {
    title: String(a.task || a.title || a.name || 'Untitled task'),
    status: String(a.status || a.action_applied || ''),
    note: truncate(a.latest_note || a.note || a.description || '')
  };
  const project = a.project_client || a.project;
  if (project) entry.project = String(project);
  return entry;
};
for (const a of applied) {
  if (a.action_applied === 'create') { counts.tasks_created += 1; counts.created.push(itemize(a)); }
  if (a.action_applied === 'update') { counts.tasks_updated += 1; counts.updated.push(itemize(a)); }
  if (a.action_applied === 'complete') { counts.tasks_completed += 1; counts.completed.push(itemize(a)); }
  if (a.doubleRunWarning) counts.doubleRunWarning = true;
  if (Array.isArray(a.errors)) counts.errors.push(...a.errors);
}
counts.tickets_auto_closed = cascades.filter(c => c && !c.error).length;
for (const c of cascades) if (c && c.error) counts.errors.push(c.error.message || JSON.stringify(c.error));
const meeting = $('Loop Per Meeting').first().json;  // current iteration meeting context
return [{ json: { ...$('Resolve Date').first().json, ...counts, meeting_title: meeting.title || 'Meeting', meeting_id: meeting.meeting_id } }];

const createProposals = $('Switch Action').all(0).map(i => i.json);
const allOpenTasks = $('Load Active Projects').all().map(i => i.json);
return createProposals.map((proposal, idx) => {
  const candidates = allOpenTasks
    .filter(t =>
      t && t.project_client === proposal.project_client &&
      t.status !== 'complete' &&
      t.status !== 'closed')
    .map(t => ({
      id: t.id,
      task: t.task,
      lead: t.lead,
      status: t.status,
      latest_note: t.latest_note || t.note || '',
      next_step: t.next_step || ''
    }));
  return {
    json: { ...proposal, candidates },
    pairedItem: { item: idx }
  };
});

return items.map((item, idx) => {
  let proposal = {};
  try { proposal = $('Apply Match Decision').itemMatching(idx).json || {}; } catch (e) { proposal = {}; }
  let dbRow = {};
  try { dbRow = $('Supabase Create WIP').itemMatching(idx).json || {}; } catch (e) { dbRow = item.json || {}; }
  const err = dbRow && dbRow.error ? [dbRow.error.message || JSON.stringify(dbRow.error)] : [];
  return {
    json: {
      action_applied: 'create',
      task: proposal.task || '',
      project_client: proposal.project_client || '',
      lead: proposal.lead || '',
      latest_note: proposal.latest_note || proposal.note || '',
      next_step: proposal.next_step || '',
      status: dbRow.status || proposal.status || '',
      existing_task_id: proposal.existing_task_id || null,
      wip_task_id: dbRow.id || null,
      errors: err
    },
    pairedItem: { item: idx }
  };
});

return items.map((item, idx) => {
  let proposal = null;
  try { const p = $('Apply Match Decision').itemMatching(idx); if (p && p.json && p.json.task) proposal = p.json; } catch (e) {}
  if (!proposal) { try { const p = $('Switch Action').itemMatching(idx); if (p && p.json && p.json.task) proposal = p.json; } catch (e) {} }
  proposal = proposal || {};
  let dbRow = {};
  try { dbRow = $('Supabase Update WIP').itemMatching(idx).json || {}; } catch (e) { dbRow = item.json || {}; }
  const err = dbRow && dbRow.error ? [dbRow.error.message || JSON.stringify(dbRow.error)] : [];
  return {
    json: {
      action_applied: 'update',
      task: proposal.task || '',
      project_client: proposal.project_client || '',
      lead: proposal.lead || '',
      latest_note: proposal.latest_note || proposal.note || '',
      next_step: proposal.next_step || '',
      status: dbRow.status || proposal.status || 'in_progress',
      existing_task_id: proposal.existing_task_id || (dbRow.id || null),
      wip_task_id: dbRow.id || proposal.existing_task_id || null,
      errors: err
    },
    pairedItem: { item: idx }
  };
});

return items.map((item, idx) => {
  let proposal = {};
  try { proposal = $('Switch Action').itemMatching(idx).json || {}; } catch (e) { proposal = {}; }
  let dbRow = {};
  try { dbRow = $('Supabase Complete WIP').itemMatching(idx).json || {}; } catch (e) { dbRow = item.json || {}; }
  const err = dbRow && dbRow.error ? [dbRow.error.message || JSON.stringify(dbRow.error)] : [];
  return {
    json: {
      action_applied: 'complete',
      task: proposal.task || '',
      project_client: proposal.project_client || '',
      lead: proposal.lead || '',
      latest_note: proposal.latest_note || proposal.note || '',
      next_step: proposal.next_step || '',
      status: 'complete',
      existing_task_id: proposal.existing_task_id || (dbRow.id || null),
      wip_task_id: dbRow.id || proposal.existing_task_id || null,
      errors: err
    },
    pairedItem: { item: idx }
  };
});
